-- Required document categories per role for the compliance report (FR-REP-005), ADR 013.

-- ============ Part 1: tables (generated by prisma migrate diff) ============
-- CreateTable
CREATE TABLE "required_document_categories" (
    "org_id" UUID NOT NULL,
    "role" VARCHAR(50) NOT NULL,
    "category" VARCHAR(20) NOT NULL,

    CONSTRAINT "required_document_categories_pkey" PRIMARY KEY ("org_id","role","category")
);

-- AddForeignKey
ALTER TABLE "required_document_categories" ADD CONSTRAINT "required_document_categories_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;



-- ============ Part 2: rules, security (hand-written) ============

ALTER TABLE required_document_categories
  ADD CONSTRAINT required_document_categories_role_check CHECK (role IN ('SUPER_ADMIN', 'ADMIN', 'HR_MANAGER', 'HR', 'MANAGER', 'TEAM_LEAD', 'EMPLOYEE', 'SUBCONTRACTOR', 'INTERN', 'AUDITOR')),
  ADD CONSTRAINT required_document_categories_category_check CHECK (category IN ('CONTRACT', 'NDA', 'IDENTITY', 'TAX', 'INVOICE', 'POLICY', 'CERTIFICATE', 'OTHER'));

ALTER TABLE required_document_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE required_document_categories FORCE ROW LEVEL SECURITY;
CREATE POLICY required_document_categories_org_policy ON required_document_categories FOR ALL
  USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid)
  WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE, DELETE ON required_document_categories TO hrvo_app;
